import { groupCount } from '@/api/safeDanger/home';
export default {
  props: ['hiddenCategory'],
  data: function data() {
    return {
      totalNumList: [{
        title: '当前隐患总量',
        value: 604
      }, {
        title: '月度新增隐患',
        value: 604
      }, {
        title: '年度新增隐患',
        value: 604
      }],
      curNumList: [{
        imgSrc: require("@/assets/safeDanger/state1.png"),
        title: '待整改',
        value: 604
      }, {
        imgSrc: require("@/assets/safeDanger/state2.png"),
        title: '整改中',
        value: 604
      }, {
        imgSrc: require("@/assets/safeDanger/state3.png"),
        title: '已整改',
        value: 604
      }, {
        imgSrc: require("@/assets/safeDanger/state4.png"),
        title: '超期未整改',
        value: 604
      }]
    };
  },
  mounted: function mounted() {
    this.getDetail();
  },
  methods: {
    goRecord: function goRecord(type) {
      // this.$router.push('/safeDanger/record?types='+type)
      this.$router.push({
        name: "Record",
        params: {
          types: type
        }
      });
    },
    getDetail: function getDetail() {
      var _this = this;
      groupCount({
        hiddenCategory: this.hiddenCategory
      }).then(function (res) {
        var data = res.data;
        _this.totalNumList[0].value = data.count;
        _this.totalNumList[1].value = data.monthCount;
        _this.totalNumList[2].value = data.yearCount;
        _this.curNumList[0].value = data.noRectified;
        _this.curNumList[1].value = data.undoRectified;
        _this.curNumList[2].value = data.doneRectified;
        _this.curNumList[3].value = data.overdueRectified;
      }).catch(function (err) {});
    }
  }
};
